<?php
declare(strict_types=1);
require_once __DIR__.'/activity.php';
final class FitnessRemoteException extends RuntimeException {public function __construct(public readonly int $status=0){parent::__construct(match($status){401=>'This activity account needs reconnection.',403=>'The provider denied activity access. Review its product access and granted read permissions.',429=>'The provider rate limit was reached. Wait before reading again.',default=>'The activity provider did not confirm this request. Review the account and try again explicitly.'});}}
function fitness_cloud(string $source): void {if(!in_array($source,['google_health','strava'],true))throw new FitnessException('Choose a supported cloud activity connection.');}
function fitness_scope(string $source,bool $private=false): string {fitness_cloud($source);return $source==='google_health'?'https://www.googleapis.com/auth/googlehealth.activity_and_fitness.readonly':($private?'read,activity:read_all':'read,activity:read');}
function fitness_http(string $method,string $url,?array $body=null,string $token=''): array {
 $valid=$method==='POST'&&in_array($url,['https://oauth2.googleapis.com/token','https://oauth2.googleapis.com/revoke','https://www.strava.com/oauth/token','https://www.strava.com/oauth/deauthorize'],true)
  ||$method==='GET'&&preg_match('~^https://(?:www\.strava\.com/api/v3/athlete(?:/activities)?|health\.googleapis\.com/v4/users/me/(?:identity|dataTypes/exercise/dataPoints))(?:\?[^#\x00-\x20]*)?$~D',$url);
 if(!$valid||strlen($url)>12000||strlen($token)>16000||preg_match('/[\x00-\x20\x7f]/',$token))throw new FitnessException('Unsupported activity provider request.');
 $raw='';$h=curl_init($url);$headers=['Accept: application/json'];if($token!=='')$headers[]='Authorization: Bearer '.$token;$options=[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>12,CURLOPT_WRITEFUNCTION=>static function($h,string $chunk)use(&$raw):int{if(strlen($raw)+strlen($chunk)>2000000)return 0;$raw.=$chunk;return strlen($chunk);}];if($body!==null){$headers[]='Content-Type: application/x-www-form-urlencoded';$options[CURLOPT_POSTFIELDS]=http_build_query($body,'','&',PHP_QUERY_RFC3986);}$options[CURLOPT_HTTPHEADER]=$headers;curl_setopt_array($h,$options);$ok=curl_exec($h)!==false;$status=(int)curl_getinfo($h,CURLINFO_RESPONSE_CODE);curl_close($h);if(!$ok||$status<200||$status>=300)throw new FitnessRemoteException($status);$data=$raw===''?[]:json_decode($raw,true);if(!is_array($data)||isset($data['error']))throw new FitnessRemoteException($status);return $data;
}
function fitness_client(string $source): array {fitness_cloud($source);return comm_get('activity.client.'.$source);}
function fitness_callback(string $source): string {fitness_cloud($source);return url('/write/activity/callback/'.$source);}
function fitness_client_input(string $source,array $in,array $reserved=[]): array {fitness_cloud($source);$id=fitness_text($in['client_id']??'',250);$secret=fitness_text($in['client_secret']??'',1000);if($id===''||$secret===''||preg_match('/\s/',$id.$secret))throw new FitnessException('Enter the dedicated provider client ID and secret.');if($source==='google_health'&&in_array($id,array_filter($reserved),true))throw new FitnessException('Use a separate Google Health OAuth client. Reusing the Workspace client could couple its revocation to other Google services.');return ['client_id'=>$id,'client_secret'=>$secret];}
function fitness_configured(array $client): bool {return !empty($client['client_id'])&&!empty($client['client_secret']);}
function fitness_client_fingerprint(array $client): string {return hash('sha256',json_encode($client,JSON_THROW_ON_ERROR));}
function fitness_authorize(string $source,int $uid,bool $private): string {
 fitness_cloud($source);$client=fitness_client($source);if(!fitness_configured($client))throw new FitnessException('Save a dedicated activity OAuth application first.');$key=fitness_key($uid,'grant',$source);$grant=comm_get($key);$state=bin2hex(random_bytes(32));$_SESSION['fitness_oauth']=['state'=>$state,'source'=>$source,'owner'=>$uid,'expires'=>time()+600,'generation'=>$grant['generation']??0,'client'=>fitness_client_fingerprint($client),'private'=>$private];
 $query=['client_id'=>$client['client_id'],'redirect_uri'=>fitness_callback($source),'response_type'=>'code','state'=>$state,'scope'=>fitness_scope($source,$private)];if($source==='google_health')$query+=['access_type'=>'offline','prompt'=>'consent'];else $query['approval_prompt']='force';return ($source==='google_health'?'https://accounts.google.com/o/oauth2/v2/auth':'https://www.strava.com/oauth/authorize').'?'.http_build_query($query,'','&',PHP_QUERY_RFC3986);
}
function fitness_identity(string $source,string $token,?callable $http=null): string {
 $http??='fitness_http';$r=$http('GET',$source==='strava'?'https://www.strava.com/api/v3/athlete':'https://health.googleapis.com/v4/users/me/identity',null,$token);
 $id=$source==='strava'?(is_int($r['id']??null)?(string)$r['id']:''):($r['healthUserId']??'');if(!is_string($id)||!preg_match('/^[A-Za-z0-9-]{1,63}$/D',$id))throw new FitnessException('The provider did not verify a linked activity identity. For Google, link the same account in the Google Health app first.');return $id;
}
function fitness_tokens(array $r): array {
 foreach(['access_token','refresh_token']as$k)if(!is_string($r[$k]??null)||$r[$k]===''||strlen($r[$k])>16000||preg_match('/[\x00-\x20\x7f]/',$r[$k]))throw new FitnessException('The provider did not return renewable activity access. Reconnect explicitly.');$expires=$r['expires_at']??(time()+(int)($r['expires_in']??0));if(!is_int($expires)||$expires<=time()||$expires>time()+31536000)throw new FitnessException('The provider returned an invalid access expiry.');return ['access_token'=>$r['access_token'],'refresh_token'=>$r['refresh_token'],'expires'=>$expires];
}
function fitness_complete(string $source,int $uid,array $query,?callable $http=null): void {
 $http??='fitness_http';$pending=$_SESSION['fitness_oauth']??[];unset($_SESSION['fitness_oauth']);$state=$query['state']??null;
 if(!is_string($state)||!is_string($pending['state']??null)||!hash_equals($pending['state'],$state)||($pending['source']??'')!==$source||($pending['owner']??0)!==$uid||($pending['expires']??0)<time()||isset($query['error']))throw new FitnessException('Activity authorization expired, was cancelled or belongs to a different session. Start again.');
 $code=$query['code']??null;if(!is_string($code)||strlen($code)>4096||$code==='')throw new FitnessException('No activity authorization code was returned.');
 comm_lock('fitness.'.$uid.'.'.$source,static function()use($source,$uid,$query,$pending,$code,$http){$client=fitness_client($source);$key=fitness_key($uid,'grant',$source);$old=comm_get($key);if(($old['generation']??0)!==$pending['generation']||!hash_equals($pending['client'],fitness_client_fingerprint($client)))throw new FitnessException('The activity connection changed. Start authorization again.');
  $r=$http('POST',$source==='strava'?'https://www.strava.com/oauth/token':'https://oauth2.googleapis.com/token',['client_id'=>$client['client_id'],'client_secret'=>$client['client_secret'],'code'=>$code,'grant_type'=>'authorization_code','redirect_uri'=>fitness_callback($source)]);
  $scopes=$source==='strava'?explode(',',is_string($query['scope']??null)?$query['scope']:''):preg_split('/\s+/',is_string($r['scope']??null)?$r['scope']:'');$needed=$source==='strava'?['read',!empty($pending['private'])?'activity:read_all':'activity:read']:[fitness_scope($source)];if(array_diff($needed,$scopes))throw new FitnessException('The required activity read permission was declined.');$tokens=fitness_tokens($r);$identity=fitness_identity($source,$tokens['access_token'],$http);
  comm_put($key,['owner'=>$uid,'source'=>$source,'identity'=>$identity,'status'=>'pending_confirmation','generation'=>$pending['generation']+1,'client'=>$pending['client'],'scopes'=>$needed,'tokens'=>$tokens,'connected_at'=>time()]);
 });
}
function fitness_live(int $uid,string $source,?callable $http=null): array {
 $http??='fitness_http';fitness_cloud($source);return comm_lock('fitness.'.$uid.'.'.$source,static function()use($uid,$source,$http){$key=fitness_key($uid,'grant',$source);$grant=comm_get($key);$client=fitness_client($source);if(($grant['owner']??0)!==$uid||($grant['status']??'')!=='connected'||!hash_equals($grant['client']??'',fitness_client_fingerprint($client)))throw new FitnessException('Connect and confirm your own activity account first.');
  try{if(($grant['tokens']['expires']??0)<time()+90){$r=$http('POST',$source==='strava'?'https://www.strava.com/oauth/token':'https://oauth2.googleapis.com/token',['client_id'=>$client['client_id'],'client_secret'=>$client['client_secret'],'grant_type'=>'refresh_token','refresh_token'=>$grant['tokens']['refresh_token']]);$r['refresh_token']??=$grant['tokens']['refresh_token'];$grant['tokens']=fitness_tokens($r);comm_put($key,$grant);}
   if(!hash_equals($grant['identity'],fitness_identity($source,$grant['tokens']['access_token'],$http)))throw new FitnessException('The activity account identity changed. Disconnect and reconnect.');return $grant;
  }catch(Throwable $e){if($e instanceof FitnessRemoteException&&in_array($e->status,[400,401],true)){$grant['status']='reconnect';comm_put($key,$grant);}throw $e;}
 });
}
function fitness_read(int $uid,string $source,array $range,?callable $http=null): array {
 $http??='fitness_http';$grant=fitness_live($uid,$source,$http);$rows=[];$seen=[];$token='';$complete=false;$cap=$source==='strava'?10:20;$began=microtime(true);
 for($page=1;$page<=$cap;$page++){
  if(microtime(true)-$began>15)break;
  if($source==='strava'){$url='https://www.strava.com/api/v3/athlete/activities?'.http_build_query(['after'=>$range['start']-1,'before'=>min(time()+1,$range['end']),'page'=>$page,'per_page'=>100]);$data=$http('GET',$url,null,$grant['tokens']['access_token']);if(!array_is_list($data)||count($data)>100)throw new FitnessException('Strava returned an invalid activity page.');foreach($data as$r){if(!in_array('activity:read_all',$grant['scopes'],true)&&(($r['private']??false)===true||($r['visibility']??'')==='only_me'))continue;$rows[]=fitness_strava_row($r);}if(count($data)<100){$complete=true;break;}}
  else{$query=['pageSize'=>25,'filter'=>'exercise.interval.civil_start_time >= "'.gmdate('Y-m-d\TH:i:s',$range['start']-86400).'" AND exercise.interval.civil_start_time < "'.gmdate('Y-m-d\TH:i:s',min(time()+86400,$range['end']+86400)).'"'];if($token!=='')$query['pageToken']=$token;$data=$http('GET','https://health.googleapis.com/v4/users/me/dataTypes/exercise/dataPoints?'.http_build_query($query,'','&',PHP_QUERY_RFC3986),null,$grant['tokens']['access_token']);if(!array_key_exists('dataPoints',$data)){if(array_diff(array_keys($data),['nextPageToken']))throw new FitnessException('Google Health returned an unknown activity envelope.');$data['dataPoints']=[];}if(!is_array($data['dataPoints'])||!array_is_list($data['dataPoints'])||count($data['dataPoints'])>25)throw new FitnessException('Google Health returned an invalid activity page.');foreach($data['dataPoints']as$r)$rows[]=fitness_google_row($r);$token=$data['nextPageToken']??'';if(!is_string($token)||strlen($token)>4096||isset($seen[$token]))throw new FitnessException('Activity pagination did not complete safely.');if($token===''){$complete=true;break;}$seen[$token]=true;}
 }
 // Prevent a concurrent disconnect/replacement from disclosing an obsolete response.
 $latest=comm_get(fitness_key($uid,'grant',$source));if(($latest['generation']??null)!==$grant['generation']||($latest['status']??'')!=='connected'||($latest['owner']??0)!==$uid)throw new FitnessException('This connection changed during the read. No report was retained.');
 return ['rows'=>fitness_unique($rows),'complete'=>$complete,'observed'=>time(),'identity'=>$grant['identity']];
}
function fitness_disconnect(int $uid,string $source,?callable $http=null): bool {
 $http??='fitness_http';fitness_cloud($source);return comm_lock('fitness.'.$uid.'.'.$source,static function()use($uid,$source,$http){$key=fitness_key($uid,'grant',$source);$g=comm_get($key);if($g&&($g['owner']??0)!==$uid)throw new FitnessException('This activity connection belongs to another Writer.');$remote=false;try{if(!empty($g['tokens']['access_token'])){$http('POST',$source==='strava'?'https://www.strava.com/oauth/deauthorize':'https://oauth2.googleapis.com/revoke',[$source==='strava'?'access_token':'token'=>$source==='strava'?$g['tokens']['access_token']:($g['tokens']['refresh_token']??$g['tokens']['access_token'])]);$remote=true;}}catch(Throwable){}comm_put($key,['owner'=>$uid,'source'=>$source,'status'=>'disconnected','generation'=>($g['generation']??0)+1]);unset($_SESSION['fitness_oauth']);return $remote;});
}
